export const getLang = () => lang;
export function setLang(l) { lang = l; try { localStorage.setItem('rt_lang', l); } catch (e) {} applyI18n(); document.dispatchEvent(new CustomEvent('langchange')); }
export function t(key, params) {
  const e = D[key]; let s = e ? (e[lang] || e.ru) : key;
  if (params) for (const k in params) s = s.replaceAll('{' + k + '}', params[k]);
  return s;
}
export function applyI18n(root = document) {
  root.querySelectorAll('[data-i18n]').forEach(el => { el.textContent = t(el.dataset.i18n); });
  document.documentElement.lang = lang === 'kz' ? 'kk' : lang; document.title = t('title');
}
export const stName = (st) => st.names[lang] || st.names.ru;
